+import static org.junit.jupiter.api.Assertions.assertTrue;
+
+@SpringBootTest
+class ContactViewTest extends SpringBrowserlessTest {
+
+    @Test
+    void emptyFormHasExpectedControlsAndValidatesOnSend() {
+        navigate(ContactView.class);
+
+        assertEquals("Contact", $(H1.class).single().getText());
+        assertEquals("About", $(RouterLink.class).single().getText());
+        assertTrue(send().isEnabled());
+        assertEquals("", name().getValue());
+        assertEquals("", email().getValue());
+        assertEquals("", phone().getValue());
+        assertEquals("", message().getValue());
+
+        test(send()).click();
+
+        assertInvalid(name(), "Name is required");
+        assertInvalid(email(), "Give an e-mail address or a phone number");
+        assertInvalid(message(), "Message is required");
+        assertFalse($(Notification.class).exists());
+    }
+
+    @Test
+    void validMessageSendsOnEnterResetsAndPersistsAcrossNavigation() {
+        navigate(ContactView.class);
+        int initialRows = test($(Grid.class).single(), ContactMessage.class).size();
+
+        test(name()).setValue("Ada");
+        test(phone()).setValue("123");
+        test(message()).setValue("Hello");
+        fireShortcut(Key.ENTER);
+
+        Notification notification = $(Notification.class).single();
+        assertTrue(test(notification).getText().contains("Message sent"));
+        assertEquals("", name().getValue());
+        assertEquals("", email().getValue());
+        assertEquals("", phone().getValue());
+        assertEquals("", message().getValue());
+        assertFalse(send().isEnabled());
+        Grid<ContactMessage> grid = grid();
+        assertEquals(initialRows + 1, test(grid).size());
+        assertEquals("Ada", test(grid).getRow(0).name());
+        assertEquals("Hello", test(grid).getRow(0).message());
+
+        navigate(AboutView.class);
+        navigate(ContactView.class);
+        assertEquals("Ada", test(grid()).getRow(0).name());
+
+        test(name()).setValue("A");
+        assertTrue(send().isEnabled());
+    }
+
+    @Test
+    void validationRetainsInputAndChecksEmailAndLength() {
+        navigate(ContactView.class);
+        test(name()).setValue("Ada");
+        test(email()).setValue("not-an-address");
+        test(message()).setValue("x".repeat(501));
+
+        test(send()).click();
+
+        assertEquals("Ada", name().getValue());
+        assertEquals("not-an-address", email().getValue());
+        assertEquals(501, message().getValue().length());
+        assertInvalid(email(), "Enter a valid e-mail address");
+        assertInvalid(message(), "Message must be at most 500 characters");
+        assertFalse($(Notification.class).exists());
+    }
+
+    @Test
+    void dirtyFormGuardsNavigationAndSupportsBothChoices() {
+        navigate(ContactView.class);
+        test(name()).setValue("Ada");
+        test($(RouterLink.class).single()).click();
+
+        assertInstanceOf(ContactView.class, getCurrentView());
+        assertTrue($(Dialog.class).single().isOpened());
+        test($(Button.class).withText("Keep editing").single()).click();
+        assertInstanceOf(ContactView.class, getCurrentView());
+        assertEquals("Ada", name().getValue());
+
+        test($(RouterLink.class).single()).click();
+        test($(Button.class).withText("Discard").single()).click();
+        assertInstanceOf(AboutView.class, getCurrentView());
+        assertEquals("About", $(H1.class).single().getText());
+    }
+
+    private TextField name() {
+        return $(TextField.class).withLabel("Name").single();
+    }
+
