+        assertTrue(field.isInvalid());
+        assertEquals(error, field.getErrorMessage());
+    }
+
+    private void assertInvalid(TextArea field, String error) {
+        assertTrue(field.isInvalid());
+        assertEquals(error, field.getErrorMessage());
+    }
